const items = $input.all();
const results = [];
const seenTitles = new Set();

for (const item of items) {
  const post = item.json;

  if (!post.id) continue;

  const likes    = Math.max(post.likesCount || 0, 0);
  const views    = Math.max(post.videoPlayCount ?? post.videoViewCount ?? 0, 0);
  const comments = Math.max(post.commentsCount || 0, 0);
  const caption  = (post.caption || '').slice(0, 800).trim();
  const hashtags = (post.hashtags || []);

  const totalEngagement = likes + views + comments;

  // Quality filters
  const hasCaption  = caption.length > 10;
  const hasHashtags = hashtags.length > 0;
  const isTrending  = totalEngagement >= 10000;

  if (!hasCaption || !hasHashtags || !isTrending) continue;

  // Music
  const asset = post.musicInfo?.music_info?.music_asset_info;

  let musicName = asset?.title || null;
  let musicUrl  = asset?.progressive_download_url
               ?? asset?.fast_start_progressive_download_url
               ?? asset?.web_30s_preview_download_url
               ?? null;

  // All-or-nothing: if either missing, drop both
  if (!musicName || !musicUrl) {
    musicName = null;
    musicUrl  = null;
  }

  // Skip duplicated title (only when music present)
  if (musicName) {
    const key = musicName.trim().toLowerCase();
    if (seenTitles.has(key)) continue;
    seenTitles.add(key);
  }

  results.push({
    json: {
      type:          post.type || null,
      caption,
      hashtags:      hashtags.join(', '),
      musicName,
      musicUrl,
      likeAmount:    likes,
      viewAmount:    views,
      commentAmount: comments,
    }
  });
}

return results;

const items = $input.all();
const batchSize = 5;
const batches = [];

// Fields to exclude
const excludeFields = ['musicName'];

// Group items into batches of 5
for (let i = 0; i < items.length; i += batchSize) {
  const batch = items.slice(i, i + batchSize);

  const posts = batch.map((item, index) => {
    const data = item.json;

    // Build clean object: exclude musicName and null/empty values
    const cleaned = {};
    for (const [key, value] of Object.entries(data)) {
      if (excludeFields.includes(key)) continue;
      if (value === null || value === undefined || value === '') continue;
      cleaned[key] = value;
    }

    return `---POST ${i + index + 1}---\n${JSON.stringify(cleaned, null, 2)}`;
  });

  batches.push({
    json: {
      batchIndex: Math.floor(i / batchSize) + 1,
      totalBatches: Math.ceil(items.length / batchSize),
      postCount: batch.length,
      prompt: posts.join('\n\n')
    }
  });
}

return batches;

// Code Node: Process Trending Post Data - Avg Likes & Comments by Media Type

const videoItems = $('GetVideo').all();
const imageItems = $('GetPost').all();

function calcStats(items) {
  if (!items || items.length === 0) {
    return {
      count: 0,
      totalLikes: 0,
      totalComments: 0,
      avgLikes: 0,
      avgComments: 0,
    };
  }

  let totalLikes = 0;
  let totalComments = 0;

  for (const item of items) {
    const data = item.json;

    totalLikes += Number(data.likeAmount) || 0;
    totalComments += Number(data.commentAmount) || 0;
  }

  const count = items.length;

  return {
    count,
    totalLikes,
    totalComments,
    avgLikes: parseFloat((totalLikes / count).toFixed(2)),
    avgComments: parseFloat((totalComments / count).toFixed(2)),
  };
}

const videoStats = calcStats(videoItems);
const imageStats = calcStats(imageItems);

// Return 2 separate n8n items
return [
  {
    json: {
      mediaType: "video",
      ...videoStats,
    },
  },
  {
    json: {
      mediaType: "imageAndSidecar",
      ...imageStats,
    },
  },
];

const trendData = $input.all().map(item => item.json);

const results = {};

for (const item of trendData) {
  const date = new Date(item.createdAt);

  const minutes = Math.floor(date.getMinutes() / 15) * 15;
  date.setMinutes(minutes, 0, 0);
  const bucketKey = date.toISOString();

  const type = item.contentType;
  const key = `${bucketKey}__${type}`;

  if (!results[key]) {
    results[key] = {
      timeBucket: bucketKey,
      contentType: type,
      totalViews: 0,
      totalLikes: 0,
      totalComments: 0,
      postCount: 0,
    };
  }

  results[key].totalViews    += item.baseView    || 0;
  results[key].totalLikes    += item.baseLike    || 0;
  results[key].totalComments += item.baseComment || 0;
  results[key].postCount     += 1;
}

const output = Object.values(results).sort((a, b) => {
  if (a.timeBucket !== b.timeBucket) return a.timeBucket.localeCompare(b.timeBucket);
  return a.contentType.localeCompare(b.contentType);
});

return output.map(item => ({ json: item }));

const items = $input.all();

const performanceTier = l =>
  l >= 200000 ? 'viral' :
  l >= 20000  ? 'high-performing' :
  l >= 2000   ? 'moderately engaging' : 'low-engagement';

const num  = v => Number(String(v ?? '').replace(/[,\s]/g, '')) || 0;
const norm = s => String(s ?? '').toLowerCase().replace(/\s+/g, ' ').trim();

const toTopics = v => (Array.isArray(v) ? v : String(v ?? '').split(','))
  .map(t => String(t).trim())
  .filter(Boolean);

const hash = s => {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (Math.imul(h, 31) + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(36);
};

// same topic set when >= 3/4 of the larger set overlaps
const topicsMatch = (a, b) => {
  if (!a.length || !b.length) return false;
  const sb = new Set(b.map(norm));
  const common = a.filter(t => sb.has(norm(t))).length;
  return common / Math.max(a.length, b.length) >= 0.75;
};

const addStats = (g, l, v, c) => { g.like += l; g.view += v; g.comment += c; };

const unionTopics = (g, topics) => {
  const seen = new Set(g.topics.map(norm));
  for (const t of topics) if (!seen.has(norm(t))) { g.topics.push(t); seen.add(norm(t)); }
};

const buckets   = new Map(); // "sentiment|contentType" -> groups[]
const byContent = new Map(); // contentHash -> group

for (const item of items) {
  const row = item.json.json ?? item.json;

  const caption = String(row.caption ?? row.content ?? '').slice(0, 800).trim();
  const topics  = toTopics(row.topics ?? row.hashtags);
  const like    = num(row.baseLike    ?? row.likeAmount);
  const view    = num(row.baseView    ?? row.viewAmount);
  const comment = num(row.baseComment ?? row.commentAmount);

  // gate: need topics + real engagement
  if (!topics.length || like + view + comment < 10000) continue;

  const contentHash = hash(norm([
    caption,
    row.contentType ?? '',
    row.sentiment ?? '',
    [...topics].sort().join(','),
  ].join('|')));

  // 1) exact same content -> sum onto existing row
  const owner = byContent.get(contentHash);
  if (owner) { addStats(owner, like, view, comment); continue; }

  // 2) fuzzy: same sentiment + contentType + >= 3/4 topic overlap
  const bucket = `${row.sentiment ?? 'unknown'}|${row.contentType ?? 'unknown'}`;
  const list = buckets.get(bucket) ?? [];
  if (!list.length) buckets.set(bucket, list);

  const dup = list.find(g => topicsMatch(g.topics, topics));
  if (dup) { addStats(dup, like, view, comment); unionTopics(dup, topics); continue; }

  const g = {
    id: row.id ?? null,
    contentType: row.contentType ?? null,
    sentiment: row.sentiment ?? null,
    caption,
    topics: [...topics],
    like, view, comment,
    createdAt: row.createdAt ?? null,
    contentHash,
  };

  list.push(g);
  byContent.set(contentHash, g);
}

const out = [];
for (const list of buckets.values()) {
  for (const g of list) {
    const topicsStr = g.topics.join(', ');

    const content = [
      g.caption || null,
      `Topics: ${topicsStr}`,
      `Type: ${g.contentType}`,
      `Sentiment: ${g.sentiment}`,
    ].filter(Boolean).join('\n');

    out.push({
      json: {
        content,
        metadata: {
          id: g.id,
          contentType: g.contentType,
          sentiment: g.sentiment,
          topics: g.topics,
          baseLike: g.like,
          baseView: g.view,
          baseComment: g.comment,
          tier: performanceTier(g.like),
          contentHash: g.contentHash,
          createdAt: g.createdAt,
        },
      },
    });
  }
}

return out;

const raw = $input.first().json.output;

const input = typeof raw === 'string' ? JSON.parse(raw) : raw;

if (!Array.isArray(input)) {
  throw new Error('Expected an array but got: ' + JSON.stringify(input));
}

return input.map(item => ({
  json: {
    ...item,
    topics: Array.isArray(item.topics) ? item.topics.join(',') : item.topics
  }
}));

const seen = new Set();
const rows = $input.all()
  .map(function (item) { return item.json; })
  .filter(function (t) { return t && typeof t === "object"; })
  .filter(function (t) {
    const key = String(t.name || "").trim().toLowerCase();
    if (!key) return true;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .slice(0, 5);

return rows.map(function (t) {
  return {
    json: {
      id: t.id,
      name: t.name,
      likeAmount: t.likeAmount,
      musicUrl: t.musicUrl
    }
  };
});

const items = $input.all();

const grouped = {};

for (const item of items) {
  const { id, createdAt, updatedAt, ...rest } = item.json;
  const type = rest.contentType;

  if (!grouped[type]) {
    grouped[type] = [];
  }

  grouped[type].push(rest);
}

return Object.entries(grouped).map(([contentType, posts]) => ({
  json: {
    contentType,
    posts
  }
}));

const items = $input.all().map(i => i.json);

// Group by contentType, then by timeStamp
const grouped = {};
for (const item of items) {
  if (!grouped[item.contentType]) grouped[item.contentType] = [];
  grouped[item.contentType].push(item);
}

// Sort each contentType's entries by timeStamp ascending
for (const type in grouped) {
  grouped[type].sort((a, b) => new Date(a.timeStamp) - new Date(b.timeStamp));
}

const calcAvg = (item, field) => item[field] / item.postAmount;
const delta = (base, current) => base === 0 ? null : +((( current - base) / base) * 100).toFixed(2);

const result = {};

for (const [contentType, entries] of Object.entries(grouped)) {
  const base = entries[0];
  const baseAvgLike    = calcAvg(base, 'likeAmount');
  const baseAvgComment = calcAvg(base, 'commentAmount');
  const baseAvgView    = calcAvg(base, 'viewAmount');

  // Combine all entries after the first
  const rest = entries.slice(1);
  if (rest.length === 0) continue;

  const combinedLike    = rest.reduce((s, e) => s + e.likeAmount, 0);
  const combinedComment = rest.reduce((s, e) => s + e.commentAmount, 0);
  const combinedView    = rest.reduce((s, e) => s + e.viewAmount, 0);
  const combinedPosts   = rest.reduce((s, e) => s + e.postAmount, 0);

  const currentAvgLike    = combinedLike    / combinedPosts;
  const currentAvgComment = combinedComment / combinedPosts;
  const currentAvgView    = combinedView    / combinedPosts;

  result[contentType] = {
    baseTimeStamp:    base.timeStamp,
    comparedTo:       rest.map(e => e.timeStamp),
    avgLikeDelta:    delta(baseAvgLike,    currentAvgLike),
    avgCommentDelta: delta(baseAvgComment, currentAvgComment),
    avgViewDelta:    delta(baseAvgView,    currentAvgView),
  };
}

return [{ json: result }];

return $input.all().map(item => {
  const { id, createdAt, updatedAt, ...rest } = item.json;
  return { json: rest };
});

const items = $input.all();

// Parse each row
const rows = items.map(item => {
  const d = item.json;
  return {
    contentType: d.contentType,
    topics: typeof d.topics === 'string'
      ? d.topics.split(',').map(t => t.trim()).filter(Boolean)
      : (Array.isArray(d.topics) ? d.topics : []),
  };
});

// Group by contentType
const byType = {};
for (const row of rows) {
  if (!byType[row.contentType]) byType[row.contentType] = [];
  byType[row.contentType].push(row);
}

// Fisher-Yates shuffle
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

const results = [];

for (const [contentType, typeRows] of Object.entries(byType)) {
  // Collect unique topics within this contentType
  const allTopics = [...new Set(typeRows.flatMap(row => row.topics))];

  // Need at least 1 topic; sets may have fewer than 3 if pool is small
  if (allTopics.length === 0) continue;

  const setSize = Math.min(3, allTopics.length);
  const usedSets = new Set();
  const maxAttempts = 200;
  let attempts = 0;
  let setsBuilt = 0;

  while (setsBuilt < 5 && attempts < maxAttempts) {
    attempts++;
    const shuffled = shuffle(allTopics);
    const set = shuffled.slice(0, setSize);
    const key = [...set].sort().join('|');

    if (usedSets.has(key)) continue;
    usedSets.add(key);

    results.push({
      json: {
        contentType,
        topics: set
      }
    });

    setsBuilt++;
  }
}

return results;

