const now = new Date();
const times = [0, 6, 12, 18];

const current = now.getHours() * 60 + now.getMinutes();

const closest = times
  .map(h => ({
    h,
    diff: ((h * 60 - current) + 1440) % 1440 || 1440
  }))
  .sort((a, b) => a.diff - b.diff)[0];

const hours = Math.floor(closest.diff / 60);
const minutes = closest.diff % 60;

const wait = hours
  ? (hours + "h" + (minutes ? " " + minutes + "m" : ""))
  : (minutes + "m");

return [{
  json: {
    reply: "Kredit chat habis. Coba lagi dalam " + wait + ".\n\nKetik /help untuk lihat perintah."
  }
}];

const output = $("FirstRun").first().json.output;
return [{ json: { reply: "Sesi aktif.

" + output + "

Ketik /help untuk lihat perintah, /stop untuk akhiri sesi." } }];

const output = $("ChatAgent").first().json.output;
let reply = String(output || "");

let sources = [];
try {
  const results = $("TavilySearch").all().flatMap(item => (item.json && item.json.results) || []);
  const seen = new Set();
  for (const item of results) {
    const url = String(item && item.url || "").trim();
    if (!url || seen.has(url)) continue;
    seen.add(url);
    sources.push(url);
    if (sources.length >= 3) break;
  }
} catch (e) {}

const missing = sources.filter(url => !reply.includes(url));
if (missing.length) {
  reply += "\n\nSumber:\n" + missing.map(url => "- " + url).join("\n");
}

return [{ json: { reply } }];

const row = $input.first().json;
if (!row.id) {
  return [{ json: { reply: "Belum ada sesi aktif. Kirim /hi untuk mulai, /help untuk lihat perintah." } }];
}
return [{ json: { reply: "Sesi dihentikan. Kredit chat tetap tersimpan.\n\nKirim /hi untuk mulai lagi, /help untuk lihat perintah." } }];

const user = $input.first().json || {};
const send = $("Send").item.json;
const text = String(send.body.text || "").trim();
const isStart = /^\/(hi|katchup)(\s|$)/i.test(text);
const session = (user.session || 0) + (isStart ? 1 : 0);
return [{ json: { ...send, sessionKey: send.body.from + "-" + session, isStart } }];

const row = $('LoadUser').first().json || {};

if (row.id === undefined || row.id === null) {
  return [{ json: { reply: "Belum ada sesi. Kirim /hi untuk mulai, /help untuk lihat perintah." } }];
}

const session = Number(row.session);
const credit = Number(row.chatCredit);
const status = String(row.status || '').toLowerCase();

const sessionText = Number.isFinite(session) && session > 0 ? '#' + session : 'belum ada';
const statusLabel = status === 'active' ? 'aktif' : status === 'stopped' ? 'berhenti' : 'belum aktif';
const creditText = (Number.isFinite(credit) ? Math.max(0, credit) : 0) + '/10';

const lines = [
  'Status Ketchy',
  '',
  'Sesi: ' + sessionText + ' (' + statusLabel + ')',
  'Kredit chat: ' + creditText,
  '',
  'Ketik /hi untuk sesi baru, /help untuk perintah.'
];

return [{ json: { reply: lines.join('\n') } }];

const row = $('LoadUser').first().json || {};
const text = String($('Send').first().json.body.text || '').trim();
const topic = text.replace(/^\/idea\b/i, '').trim().slice(0, 200);

const fail = (reply) => [{ json: { ok: false, reply } }];

if (row.id === undefined || row.id === null) return fail('Sesi belum aktif. Kirim /hi dulu untuk mulai.');
if (String(row.status || '').toLowerCase() !== 'active') return fail('Sesi belum aktif. Kirim /hi dulu untuk mulai.');
const credit = Number(row.chatCredit);
if (!Number.isFinite(credit) || credit < 1) return fail('Kredit chat habis. Kredit di-refresh tiap 6 jam.');
if (!topic) return fail('Tulis topiknya ya. Contoh: /idea kuliner rumahan');

return [{ json: { ok: true, topic } }];

const topic = $('IdeaCmd').first().json.topic;
const rows = $input.all().map(i => i.json).filter(r => r && r.contentType);

const byType = {};
for (const r of rows) {
  const type = String(r.contentType || '').toLowerCase();
  if (!type) continue;
  const bucket = byType[type] || (byType[type] = { likes: [], topics: new Set() });
  const like = Number(r.baseLike);
  if (Number.isFinite(like) && like > 0) bucket.likes.push(like);
  String(r.topics || '').split(',').map(t => t.trim()).filter(Boolean).forEach(t => bucket.topics.add(t));
}

const caps = {};
const stats = Object.entries(byType).map(([type, b]) => {
  const likes = [...b.likes].sort((a, c) => a - c);
  const median = likes.length ? likes[Math.floor(likes.length / 2)] : 0;
  const max = likes.length ? likes[likes.length - 1] : 0;
  caps[type] = Math.min(Math.round(max * 1.5), Math.max(Math.round(median * 5), 25000));
  return type + ': median likes ' + median + ', max likes ' + max + ', contoh topik: ' + [...b.topics].slice(0, 8).join(', ');
}).join('\n');

const prompt = 'Topik dari kreator: "' + topic + '"\n\n' +
'Statistik data Katchup per kategori (dari 837 contoh post):\n' + stats + '\n\n' +
'Buat tepat 3 ide konten Instagram untuk topik itu, masing-masing dengan kategori Katchup yang paling cocok.\n\n' +
'Aturan ide:\n' +
'- Bahasa Indonesia santai, seperti orang Indonesia ngobrol di medsos. Bukan terjemahan kaku.\n' +
'- Tepat 2 kalimat, satu paragraf, tanpa baris baru. Kalimat 1 mendeskripsikan wujud kontennya (mulai dengan "video pendek yang...", "foto yang...", "carousel yang..."), kalimat 2 menjelaskan hook atau sudut pandangnya.\n' +
'- Wajib berakar pada keseharian, budaya, atau konteks Indonesia. Ambil sudut tidak terduga.\n' +
'- Dilarang membuka dengan "Konten ini", "Ide ini", "Kontennya", atau menyebut nama topik di awal kalimat. Dilarang memakai "temukan", "eksplorasi", "yuk kenali", "tahukah kamu", "simak".\n' +
'- Jangan menyebut angka data, nama tool, atau kata "data" di dalam ide.\n\n' +
'Aturan estimatedLike: pakai kategori yang dipilih, kalibrasi dari median dan max di atas. Ambil sikap highball (batas atas tier yang masuk akal), jangan lewat 1.5x max likes kategori itu.\n\n' +
'Keluarkan HANYA JSON array berisi 3 object, tanpa markdown. Key: contentIdea, contentType, topics (3-5 tag dipisah koma), estimatedLike.';

return [{ json: { prompt, caps } }];

const parsed = $json.output ?? $json;
const list = Array.isArray(parsed) ? parsed : (Array.isArray(parsed && parsed.ideas) ? parsed.ideas : []);
if (!list.length) throw new Error('IdeaChain returned no ideas');

const ctx = $('IdeaCmd').first().json;
const from = $('Send').first().json.body.from;
const allowed = ['education', 'lifestyle', 'news', 'politics', 'humor', 'culture', 'food'];
const caps = ($('IdeaPrompt').first().json.caps) || {};

return list.slice(0, 3).map((idea) => ({
  json: {
    from,
    topic: ctx.topic,
    contentIdea: String(idea.contentIdea || '').trim(),
    contentType: allowed.includes(idea.contentType) ? idea.contentType : 'lifestyle',
    topics: String(idea.topics || '').trim(),
    estimatedLike: Math.min(
      Math.max(0, Math.round(Number(idea.estimatedLike) || 0)),
      Number.isFinite(Number(caps[idea.contentType])) ? Number(caps[idea.contentType]) : 1000000
    )
  }
}));

const ideas = $('IdeaFormat').all().map(i => i.json);
const topic = $('IdeaCmd').first().json.topic;
const lines = ['3 ide konten buat "' + topic + '":', ''];

ideas.forEach((idea, idx) => {
  lines.push((idx + 1) + '. ' + idea.contentIdea);
  lines.push('   ' + idea.contentType + ' - est. ' + Number(idea.estimatedLike).toLocaleString('id-ID') + ' likes');
  lines.push('');
});

lines.push('Ide disimpan di riwayat Ketchy kamu.');
lines.push('Ketik /idea <topik> buat ide lain, /status buat cek kredit.');
return [{ json: { reply: lines.join('\n') } }];
